"""Cutest-picture-01 entry: write the art to the output directory.

The art is a baby red panda holding a bamboo leaf, embedded below as
base64 (a JPEG by its magic bytes; the name stays entry.png either
way, per the rules). The program decodes it to
$MAKEFUN_OUTPUT_DIR/entry.png, defaulting to /output.
"""

import base64
import os

B64 = ""

DST_DIR = os.environ.get("MAKEFUN_OUTPUT_DIR", "/output")

os.makedirs(DST_DIR, exist_ok=True)
dst = os.path.join(DST_DIR, "entry.png")
data = base64.b64decode(B64)
with open(dst, "wb") as f:
    f.write(data)

# Fail loudly on a truncated write instead of shipping a broken image.
if os.path.getsize(dst) != len(data):
    raise RuntimeError("entry.png write is incomplete")
